def solve(grid):
    # Mapping from column index of the single '5' in a row to the output value
    col_to_value = {0: 2, 1: 4, 2: 3}

    nrows = len(grid)
    ncols = len(grid[0]) if nrows else 0

    output = []
    for row in grid:
        # Find the column that contains the value 5 (assumed exactly one per row)
        try:
            col = row.index(5)
        except ValueError:
            col = -1  # no 5 in this row

        value = col_to_value.get(col, 0)  # default to 0 if column not recognized
        output.append([value] * ncols)

    return output

